@Test
@Transactional
void 팀_없음() {
    em.persist(new Member("팀없음", 10));
    em.flush(); em.clear();

    for (NestedClosed r : memberRepository.findNestedByAge(10)) {
        System.out.println(r.getUsername() + " / " +
                (r.getTeam() == null ? "없음" : r.getTeam().getName()));
    }
}

