@Test
@Transactional
void 정리() {
    record C(String name, Runnable r) {}
    for (C c : List.of(
            new C("엔티티",  () -> memberRepository.findByAge(10)),
            new C("중첩",    () -> memberRepository.findNestedByAge(10)),
            new C("두 칸",   () -> memberRepository.findDeepByAge(10)),
            new C("평평",    () -> memberRepository.findFlatByAge(10)),
            new C("new",     () -> memberRepository.findFlatDtoByAge(10)))) {
        em.clear();
        System.out.printf("%-8s %2d개%n", c.name(),
                sqlCapture.columnCount(c.r()));
    }
}

