-- 시간도 잰다

@Test
@Transactional
void 시간() {
    for (String kind : List.of("중첩", "평평")) {
        em.clear();
        long t = System.nanoTime();
        if (kind.equals("중첩")) memberRepository.findNestedByAge(10);
        else                     memberRepository.findFlatByAge(10);
        System.out.printf("%-6s %d ms%n", kind,
                (System.nanoTime() - t) / 1_000_000);
    }
}

